∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v g : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    ∀ᵐ (σ : ℝ) ∂MeasureTheory.volume.restrict (Set.Icc 0 1),
      ∫⁻ (y : Breakdown.Space), ENNReal.ofReal (Breakdown.matSq (G σ y)) < ⊤

∀ (L : Breakdown.Space →L[ℝ] Breakdown.Space) {V : Breakdown.Space → Breakdown.Space}
  {D : Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space},
  Breakdown.IsWeakGradient V D → Breakdown.IsWeakGradient (fun y => L (V y)) fun y => L ∘SL D y

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    ∫⁻ (s : ℝ) in Set.Icc (-2) 2, ∫⁻ (y : Breakdown.Space), ENNReal.ofReal (Breakdown.matSq (G s y)) < ⊤

∀ {Γ : Set Breakdown.Symmetry} {P w₀ : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  0 ≤ w₀ →
    Breakdown.IsPerturbation Γ P v G H g →
      (Breakdown.periodLIntegral fun σ y => ‖Breakdown.secondDerivTrace (H σ y)‖ ^ 2 + w₀ * Breakdown.matSq (G σ y)) < ⊤

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    ∫⁻ (s : ℝ) in Set.Icc (-2) 2, (∫⁻ (y : Breakdown.Space), ENNReal.ofReal ‖v s y‖ ^ 6) ^ (1 / 3) < ⊤

∀ {X : Type u_1} {inst : NormedAddCommGroup X} {inst_1 : InnerProductSpace ℝ X} {inst_2 : CompleteSpace X}
  {G : ℝ → X →L[ℝ] X} {G_zero : G 0 = ContinuousLinearMap.id ℝ X}
  {G_add : ∀ (s t : ℝ), 0 ≤ s → 0 ≤ t → G (s + t) = G s ∘SL G t} {G_norm : ∀ (t : ℝ), 0 ≤ t → ‖G t‖ ≤ 1}
  {G_cont : ∀ (x : X), ContinuousOn (fun t => (G t) x) (Set.Ici 0)} {K : ℝ → X →L[ℝ] X →L[ℝ] X}
  {K_symm : ∀ (τ : ℝ) (u v : X), ((K τ) u) v = ((K τ) v) u} {CK : ℝ}
  {K_bound : ∀ (τ : ℝ), 0 < τ → τ ≤ 1 → ‖K τ‖ ≤ CK * τ ^ (-(3 / 4))}
  {K_cont : ∀ (u v : X), ContinuousOn (fun τ => ((K τ) u) v) (Set.Ioi 0)}
  {K_shift : ∀ (s τ : ℝ), 0 ≤ s → 0 < τ → ∀ (u v : X), (G s) (((K τ) u) v) = ((K (s + τ)) u) v} {D : ℝ → X →L[ℝ] X}
  {D_norm : ∀ (μ : ℝ), 0 < μ → ∀ (u : X), ‖(D μ) u‖ = μ ^ (1 / 4) * ‖u‖} {D_one : D 1 = ContinuousLinearMap.id ℝ X}
  {D_mul : ∀ (μ ν : ℝ), 0 < μ → 0 < ν → D (μ * ν) = D μ ∘SL D ν}
  {D_cont : ∀ (u : X), ContinuousOn (fun μ => (D μ) u) (Set.Ioi 0)}
  {D_G : ∀ (μ t : ℝ), 0 < μ → 0 ≤ t → D μ ∘SL G (μ * t) = G t ∘SL D μ}
  {D_K : ∀ (μ τ : ℝ), 0 < μ → 0 < τ → ∀ (u v : X), μ • (D μ) (((K (μ * τ)) u) v) = ((K τ) ((D μ) u)) ((D μ) v)}
  {compact : ∃ S, Dense S ∧ ∀ f ∈ S, ∀ (τ : ℝ), 0 < τ → IsCompactOperator ⇑((K τ) f)} {G_1 : ℝ → X →L[ℝ] X}
  {G_zero_1 : G_1 0 = ContinuousLinearMap.id ℝ X} {G_add_1 : ∀ (s t : ℝ), 0 ≤ s → 0 ≤ t → G_1 (s + t) = G_1 s ∘SL G_1 t}
  {G_norm_1 : ∀ (t : ℝ), 0 ≤ t → ‖G_1 t‖ ≤ 1} {G_cont_1 : ∀ (x : X), ContinuousOn (fun t => (G_1 t) x) (Set.Ici 0)}
  {K_1 : ℝ → X →L[ℝ] X →L[ℝ] X} {K_symm_1 : ∀ (τ : ℝ) (u v : X), ((K_1 τ) u) v = ((K_1 τ) v) u} {CK_1 : ℝ}
  {K_bound_1 : ∀ (τ : ℝ), 0 < τ → τ ≤ 1 → ‖K_1 τ‖ ≤ CK_1 * τ ^ (-(3 / 4))}
  {K_cont_1 : ∀ (u v : X), ContinuousOn (fun τ => ((K_1 τ) u) v) (Set.Ioi 0)}
  {K_shift_1 : ∀ (s τ : ℝ), 0 ≤ s → 0 < τ → ∀ (u v : X), (G_1 s) (((K_1 τ) u) v) = ((K_1 (s + τ)) u) v}
  {D_1 : ℝ → X →L[ℝ] X} {D_norm_1 : ∀ (μ : ℝ), 0 < μ → ∀ (u : X), ‖(D_1 μ) u‖ = μ ^ (1 / 4) * ‖u‖}
  {D_one_1 : D_1 1 = ContinuousLinearMap.id ℝ X} {D_mul_1 : ∀ (μ ν : ℝ), 0 < μ → 0 < ν → D_1 (μ * ν) = D_1 μ ∘SL D_1 ν}
  {D_cont_1 : ∀ (u : X), ContinuousOn (fun μ => (D_1 μ) u) (Set.Ioi 0)}
  {D_G_1 : ∀ (μ t : ℝ), 0 < μ → 0 ≤ t → D_1 μ ∘SL G_1 (μ * t) = G_1 t ∘SL D_1 μ}
  {D_K_1 :
    ∀ (μ τ : ℝ), 0 < μ → 0 < τ → ∀ (u v : X), μ • (D_1 μ) (((K_1 (μ * τ)) u) v) = ((K_1 τ) ((D_1 μ) u)) ((D_1 μ) v)}
  {compact_1 : ∃ S, Dense S ∧ ∀ f ∈ S, ∀ (τ : ℝ), 0 < τ → IsCompactOperator ⇑((K_1 τ) f)},
  { G := G, G_zero := G_zero, G_add := G_add, G_norm := G_norm, G_cont := G_cont, K := K, K_symm := K_symm, CK := CK,
        K_bound := K_bound, K_cont := K_cont, K_shift := K_shift, D := D, D_norm := D_norm, D_one := D_one,
        D_mul := D_mul, D_cont := D_cont, D_G := D_G, D_K := D_K, compact := compact } =
      { G := G_1, G_zero := G_zero_1, G_add := G_add_1, G_norm := G_norm_1, G_cont := G_cont_1, K := K_1,
        K_symm := K_symm_1, CK := CK_1, K_bound := K_bound_1, K_cont := K_cont_1, K_shift := K_shift_1, D := D_1,
        D_norm := D_norm_1, D_one := D_one_1, D_mul := D_mul_1, D_cont := D_cont_1, D_G := D_G_1, D_K := D_K_1,
        compact := compact_1 } →
    G = G_1 ∧ K = K_1 ∧ CK = CK_1 ∧ D = D_1

∀ {k : ℕ} {Γ : Set Breakdown.Symmetry} {P C R₀ : ℝ} {v g : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {χ : Fin k → ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space} {pd : Breakdown.AdjointDefect.PinData k}
  (c : Fin k → ℝ),
  Breakdown.IsPerturbation Γ P v G H g →
    Breakdown.AdjointDefect.IsPinData χ pd C R₀ →
      ∀ᵐ (σ : ℝ) ∂MeasureTheory.volume.restrict (Set.Icc 0 1),
        ∫ (y : Breakdown.Space),
            Breakdown.matInner (G σ y) (ContinuousLinearMap.adjoint (∑ l, c l • fderiv ℝ (pd.generator l σ) y)) =
          0

∀ {k : ℕ} {χ : Fin k → ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {p : Breakdown.AdjointDefect.PinData k} {C R₀ : ℝ},
  Breakdown.AdjointDefect.IsPinData χ p C R₀ → ∀ (l : Fin k), Breakdown.IsTimePeriodic (p.generator l)

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CellReduction.Instantiation.ProfileShapeEntry k}
  {Pr : Breakdown.CellReduction.Instantiation.PressureShapeEntry k}
  {Z : Breakdown.CellReduction.Instantiation.AdjointShapeEntry k}
  {O : Breakdown.CellReduction.Instantiation.OffsetExpansionEntry k}
  (H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space),
  Breakdown.CellReduction.Instantiation.IsOffsetExpansionEntry D R Pr Z O →
    Breakdown.CellReduction.Instantiation.IsOffsetExpansionEntry
      { cert := D.cert, pieces := D.pieces, bounds := D.bounds, given := D.given, givenHess := H,
        givenLabels := D.givenLabels, azimuthOrder := D.azimuthOrder, mesh := D.mesh, rows := D.rows, model := D.model,
        modelErrors := D.modelErrors, charges := D.charges, pinValues := D.pinValues,
        actuatorValues := D.actuatorValues, coercivity := D.coercivity, formCoercivity := D.formCoercivity,
        pinWeight := D.pinWeight }
      R Pr Z O

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v g : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    MeasureTheory.Integrable (fun z => Breakdown.matSq (G z.1 z.2)) Breakdown.AdjointDefect.Internal.periodMeasure

∀ {Γ : Set Breakdown.Symmetry} {P w₀ : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  0 ≤ w₀ →
    Breakdown.IsPerturbation Γ P v G H g →
      (Breakdown.periodLIntegral fun σ y => ‖Breakdown.secondDerivTrace (H σ y)‖ ^ 2 + w₀ * Breakdown.matSq (G σ y)) < ⊤

∀ {k : ℕ} {χ : Fin k → ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {p : Breakdown.AdjointDefect.PinData k} {C R₀ : ℝ},
  Breakdown.AdjointDefect.IsPinData χ p C R₀ → ∀ (l : Fin k), ContDiff ℝ 1 fun z => p.generator l z.1 z.2

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    ∀ᵐ (s : ℝ), s ∈ Set.Icc (-2) 2 → ∫⁻ (y : Breakdown.Space), ENNReal.ofReal (Breakdown.matSq (G s y)) < ⊤

∀ {ι : Type u_1} {M : Type u_3} {N : Type u_4} [inst : AddCommMonoid M] [inst_1 : AddCommMonoid N] {G : Type u_7}
  [inst_2 : FunLike G M N] [AddMonoidHomClass G M N] (g : G) (f : ι → M) (s : Finset ι),
  ∑ x ∈ s, g (f x) = g (∑ x ∈ s, f x)

∀ {F : Type u_1} [inst : NormedAddCommGroup F] [inst_1 : NormedSpace ℝ F] {l : ℝ → F} {l' : F} {u : Breakdown.Space → ℝ}
  {U : Breakdown.Space →L[ℝ] ℝ} {y : Breakdown.Space},
  HasDerivAt l l' (u y) → HasFDerivAt u U y → ∃ D, HasFDerivAt (fun z => l (u z)) D y ∧ ‖D‖ ≤ ‖l'‖ * ‖U‖

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CellReduction.Instantiation.ProfileShapeEntry k}
  {Pr : Breakdown.CellReduction.Instantiation.PressureShapeEntry k}
  {Z : Breakdown.CellReduction.Instantiation.AdjointShapeEntry k}
  (H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space),
  Breakdown.CellReduction.Instantiation.InstantiationBounded D R Pr Z →
    Breakdown.CellReduction.Instantiation.InstantiationBounded
      { cert := D.cert, pieces := D.pieces, bounds := D.bounds, given := D.given, givenHess := H,
        givenLabels := D.givenLabels, azimuthOrder := D.azimuthOrder, mesh := D.mesh, rows := D.rows, model := D.model,
        modelErrors := D.modelErrors, charges := D.charges, pinValues := D.pinValues,
        actuatorValues := D.actuatorValues, coercivity := D.coercivity, formCoercivity := D.formCoercivity,
        pinWeight := D.pinWeight }
      R Pr Z

∀ {T : ℝ → Breakdown.Space → Breakdown.Space} {K : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {C C' γ : ℝ},
  Breakdown.AdjointDefect.IsResidualField T K C γ → C ≤ C' → Breakdown.AdjointDefect.IsResidualField T K C' γ

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    ∫⁻ (s : ℝ) in Set.Icc (-2) 2, ∫⁻ (y : Breakdown.Space), ENNReal.ofReal (‖v s y‖ / (1 + ‖y‖)) ^ 2 < ⊤

∀ {Γ : Set Breakdown.Symmetry} {P w₀ : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  0 < w₀ →
    Breakdown.IsPerturbation Γ P v G H g →
      (Breakdown.periodLIntegral fun σ y => ‖Breakdown.secondDerivTrace (H σ y)‖ ^ 2 + w₀ * Breakdown.matSq (G σ y)) < ⊤

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v g : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    ∀ {w₀ : ℝ}, 0 < w₀ → Breakdown.AdjointDefect.gradientNorm G ≤ √(Breakdown.weightedEnergy (fun x => w₀) G H) / √w₀
